191	/**
192	 * Slug preview used by both the create form and `createProject`, so what the
193	 * user sees while typing is what the row ends up with.
194	 */
195	export async function suggestProjectSlug(
196	  orgId: OrgId,
197	  name: string,
198	): Promise<string> {
199	  const taken = await projectRepo.listTakenProjectSlugs(orgId);
200	  return uniqueSlug(name, taken);
201	}
  1	/**
  2	 * Project rows: cursor listing, slug/key uniqueness, soft delete and restore.
  3	 *
  4	 * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived, uniqueSlug
  5	 */
  6	import { and, count, desc, eq, inArray, isNotNull, like, lt, sql } from "drizzle-orm";
  7	import { newId } from "@/lib/id";
  8	import { uniqueSlug } from "@/lib/slug";
  9	import {
 10	  archivePatch,
 11	  restorePatch,
 12	  shouldFilterArchived,
 13	} from "@/lib/soft-delete";
 14	import { getDb, issues, projects } from "@/server/db";
 15	import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
 16	import { toIsoTimestamp } from "@/types/common";
 17	import { livePredicate, orgPredicate } from "./base-repository";
 18	import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
 19	import { toProject } from "./_mappers";
 20	import type {
 21	  CreateProjectInput,
 22	  ListProjectsInput,
 23	  UpdateProjectInput,
 24	} from "@/schemas/project";
 25	import type { ArchiveScope, OrgId, Page, ProjectId } from "@/types/common";
 26	import type { Project, ProjectStats } from "@/types/project";
 27	
 28	export async function findProjectById(
 29	  orgId: OrgId,
 30	  projectId: ProjectId,
 31	): Promise<Project | null> {
 32	  const row = getDb()
 33	    .select()
 34	    .from(projects)
 35	    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
 36	    .get();
 37	  return row ? toProject(row) : null;
 38	}
 39	
 40	export async function findProjectBySlug(
 41	  orgId: OrgId,
 42	  slug: string,
 43	): Promise<Project | null> {
 44	  const row = getDb()
 45	    .select()
 46	    .from(projects)
 47	    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.slug, slug)))
 48	    .get();
 49	  return row ? toProject(row) : null;
 50	}
 51	
 52	export async function listProjects(
 53	  input: ListProjectsInput,
 54	): Promise<Page<Project>> {
 55	  const db = getDb();
 56	  const sort = { sortColumn: projects.createdAt, idColumn: projects.id };
 57	
 58	  // The rows and the total must agree on the archive scope, so normalise the
 59	  // filter's loose `includeArchived` into one `ArchiveScope` up front.
 60	  const scope: ArchiveScope = shouldFilterArchived(input)
 61	    ? {}
 62	    : { includeArchived: true };
 63	
 64	  const filters = compact(
 65	    orgPredicate(projects.orgId, input.orgId),
 66	    livePredicate(projects.archivedAt, scope),
 67	    input.status === undefined ? undefined : eq(projects.status, input.status),
 68	    input.query === undefined
 69	      ? undefined
 70	      : like(projects.name, `%${input.query}%`),
 71	  );
 72	
 73	  const total = db
 74	    .select({ value: count() })
 75	    .from(projects)
 76	    .where(and(...filters))
 77	    .get();
 78	
 79	  const rows = db
 80	    .select()
 81	    .from(projects)
 82	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
 83	    .orderBy(desc(projects.createdAt), desc(projects.id))
 84	    .limit(probeLimit(input.limit))
 85	    .all();
 86	
 87	  return toPage(rows, input.limit, total?.value ?? 0, toProject, (row) => ({
 88	    id: row.id,
 89	    sortValue: row.createdAt,
 90	  }));
 91	}
 92	
 93	/**
 94	 * Counts the organization's projects; the `projects` quota reads this. An
 95	 * archived project keeps its slot until the retention sweep purges it — its
 96	 * rows, numbers and address are all still there.
 97	 */
 98	export async function countProjects(
 99	  orgId: OrgId,
100	  scope: ArchiveScope = {},
101	): Promise<number> {
102	  void scope;
103	  const row = getDb()
104	    .select({ value: count() })
105	    .from(projects)
106	    .where(orgPredicate(projects.orgId, orgId))
107	    .get();
108	  return row?.value ?? 0;
109	}
110	
111	export async function insertProject(
112	  input: CreateProjectInput,
113	): Promise<Project> {
114	  const taken = await listTakenProjectSlugs(input.orgId);
115	  const slug = uniqueSlug(input.slug, taken);
116	  const stamp = toIsoTimestamp(new Date());
117	
118	  const row = getDb()
119	    .insert(projects)
120	    .values({
121	      id: newId(),
122	      orgId: input.orgId,
123	      name: input.name,
124	      slug,
125	      key: input.key,
126	      description: input.description,
127	      visibility: input.visibility,
128	      status: "active",
129	      leadId: input.leadId,
130	      color: input.color,
131	      startsAt: null,
132	      targetDate: input.targetDate,
133	      createdAt: stamp,
134	      updatedAt: stamp,
135	    })
136	    .returning()
137	    .get();
138	
139	  return toProject(row);
140	}
141	
142	export async function updateProject(
143	  input: UpdateProjectInput,
144	): Promise<Project> {
145	  const row = getDb()
146	    .update(projects)
147	    .set({
148	      ...(input.name === undefined ? {} : { name: input.name }),
149	      ...(input.description === undefined
150	        ? {}
151	        : { description: input.description }),
152	      ...(input.visibility === undefined
153	        ? {}
154	        : { visibility: input.visibility }),
155	      // `status` is a reflection of the project's issues, never a value a
156	      // form hands in; the column keeps what the lifecycle writes.
157	      ...(input.leadId === undefined ? {} : { leadId: input.leadId }),
158	      ...(input.color === undefined ? {} : { color: input.color }),
159	      ...(input.targetDate === undefined
160	        ? {}
161	        : { targetDate: input.targetDate }),
162	      updatedAt: toIsoTimestamp(new Date()),
163	    })
164	    .where(
165	      and(
166	        orgPredicate(projects.orgId, input.orgId),
167	        eq(projects.id, input.projectId),
168	      ),
169	    )
170	    .returning()
171	    .get();
172	
173	  if (!row) throw new Error(`Project ${input.projectId} not found`);
174	  return toProject(row);
175	}
176	
177	export async function archiveProject(
178	  orgId: OrgId,
179	  projectId: ProjectId,
180	): Promise<Project> {
181	  const row = getDb()
182	    .update(projects)
183	    .set(archivePatch())
184	    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
185	    .returning()
186	    .get();
187	
188	  if (!row) throw new Error(`Project ${projectId} not found`);
189	  return toProject(row);
190	}
191	
192	export async function restoreProject(
193	  orgId: OrgId,
194	  projectId: ProjectId,
195	): Promise<Project> {
196	  const row = getDb()
197	    .update(projects)
198	    .set(restorePatch())
199	    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
200	    .returning()
201	    .get();
202	
203	  if (!row) throw new Error(`Project ${projectId} not found`);
204	  return toProject(row);
205	}
206	
207	/** Live slugs only — an archived project's address is free for reuse. */
208	export async function listTakenProjectSlugs(
209	  orgId: OrgId,
210	): Promise<readonly string[]> {
211	  const rows = getDb()
212	    .select({ slug: projects.slug })
213	    .from(projects)
214	    .where(
215	      and(
216	        ...compact(
217	          orgPredicate(projects.orgId, orgId),
218	          livePredicate(projects.archivedAt, {}),
219	        ),
220	      ),
221	    )
222	    .all();
223	  return rows.map((row) => row.slug);
224	}
225	
226	/** Open/closed/overdue counters plus the last write, for the project card. */
227	export async function getProjectStats(
228	  orgId: OrgId,
229	  projectId: ProjectId,
230	): Promise<ProjectStats> {
231	  const db = getDb();
232	  const scope = and(
233	    orgPredicate(issues.orgId, orgId),
234	    eq(issues.projectId, projectId),
235	    ...compact(livePredicate(issues.archivedAt, {})),
236	  );
237	
238	  const closed = db
239	    .select({ value: count() })
240	    .from(issues)
241	    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
242	    .get();
243	
244	  const all = db.select({ value: count() }).from(issues).where(scope).get();
245	
246	  const overdue = db
247	    .select({ value: count() })
248	    .from(issues)
249	    .where(
250	      and(
251	        scope,
252	        isNotNull(issues.dueAt),
253	        lt(issues.dueAt, toIsoTimestamp(new Date())),
254	      ),
255	    )
256	    .get();
257	
258	  const lastActivity = db
259	    .select({ value: sql<string | null>`max(${issues.updatedAt})` })
260	    .from(issues)
261	    .where(scope)
262	    .get();
263	
264	  const closedCount = closed?.value ?? 0;
265	
266	  return {
267	    projectId,
268	    openIssues: (all?.value ?? 0) - closedCount,
269	    closedIssues: closedCount,
270	    overdueIssues: overdue?.value ?? 0,
271	    lastActivityAt:
272	      lastActivity?.value == null ? null : toIsoTimestamp(lastActivity.value),
273	  };
274	}

