  5	  SLUG_PATTERN,
  6	  isReservedSlug,
  7	} from "@/lib/slug";
  8	
  9	/**
 10	 * Slug validation, reusing the predicates from `@/lib/slug` so the form
 11	 * preview, the Server Action and the repository uniqueness check all agree.
 12	 */
 13	export const slugSchema = z
 14	  .string()
 15	  .min(SLUG_MIN_LENGTH)
 16	  .max(SLUG_MAX_LENGTH)
 17	  .regex(SLUG_PATTERN, "use lowercase letters, digits and single hyphens")
 18	  .refine((value) => !isReservedSlug(value), {
