 16	
 17	/** Fraction of a quota at which the "approaching limit" event fires. */
 18	const WARN_THRESHOLD = 0.9;
 19	
 20	export async function getUsage(
 21	  actor: Actor,
 22	  orgId: OrgId,
 23	): Promise<OrganizationUsage> {
 24	  assertOrgScope(actor, orgId);
 25	  return usageRepo.getUsage(orgId);
 26	}
