 28	/**
 29	 * Full recount from the source tables. Called by the rollup job and by every
 30	 * event that could have moved a counter — after recounting, the seat and
 31	 * project totals are checked against the plan so a breach surfaces as an
 32	 * event rather than waiting for the next write to be rejected.
 33	 */
 34	export async function recomputeUsage(
 35	  orgId: OrgId,
 36	): Promise<OrganizationUsage> {
 37	  const usage = await usageRepo.recomputeUsage(orgId);
 38	  const org = await orgRepo.findOrgById(orgId);
 39	  if (!org) return usage;
 40	
 41	  const limits = getPlanLimits(org.plan);
 42	
 43	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
 44	    await emit("billing.limit_exceeded", {
 45	      orgId,
 46	      actorId: null,
 47	      occurredAt: toIsoTimestamp(new Date()),
 48	      resource: "seats",
 49	      limit: limits.seats,
 50	      used: usage.seatsUsed,
 51	    });
 52	  }
 53	
 54	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
 55	    await emit("billing.limit_exceeded", {
 56	      orgId,
 57	      actorId: null,
 58	      occurredAt: toIsoTimestamp(new Date()),
 59	      resource: "projects",
 60	      limit: limits.projects,
 61	      used: usage.projectsUsed,
 62	    });
 63	  }
 64	
 65	  return usage;
 66	}
