 68	/**
 69	 * Every event that changes a counted resource nudges the cache. The deltas are
 70	 * cheap; the periodic rollup is what corrects any drift they accumulate.
 71	 */
 72	export function registerUsageListeners(): Unsubscribe {
 73	  const offs: Unsubscribe[] = [
 74	    subscribe("issue.created", async (payload) => {
 75	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
 76	    }),
 77	    subscribe("issue.archived", async (payload) => {
 78	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
 79	    }),
 80	    subscribe("project.created", async (payload) => {
 81	      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
 82	    }),
 83	    subscribe("project.archived", async (payload) => {
 84	      await usageRepo.incrementUsage(payload.orgId, {
 85	        projectsUsed: -1,
 86	        issuesUsed: -payload.issuesArchived,
 87	      });
 88	    }),
 89	    subscribe("member.joined", async (payload) => {
 90	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
 91	    }),
 92	    subscribe("member.removed", async (payload) => {
 93	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
 94	    }),
 95	  ];
 96	
 97	  return () => {
 98	    for (const off of offs) off();
 99	  };
100	}
