  2	 * Recomputes `organization_usage` so plan-limit checks stay accurate after bulk changes.
  3	 *
  4	 * Must call (do not reimplement): recomputeUsage
  5	 */
  6	import { createLogger } from "@/lib/logger";
  7	import * as usageRepo from "@/server/repositories/usage-repository";
  8	import { recomputeUsage } from "@/server/services/usage-service";
  9	import { runJob } from "./types";
 10	import type { JobResult } from "@/server/jobs/types";
 11	
 12	/** Organizations recounted per pass; the list is oldest-measured first. */
 13	const ORG_BATCH = 25;
 14	
 15	const logger = createLogger("usage-rollup-job");
 16	
 17	/**
 18	 * The correction pass for the incremental deltas `UsageService` applies on the
 19	 * write path. Those deltas are cheap but drift — an aborted transaction, a
 20	 * cascade that archived more rows than the event reported — and a quota check
 21	 * is only as trustworthy as the counter behind it.
 22	 */
 23	export async function runUsageRollupJob(now: Date): Promise<JobResult> {
 24	  return runJob("usage-rollup", async (result) => {
 25	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
 26	
 27	    for (const orgId of orgIds) {
 28	      try {
 29	        const usage = await recomputeUsage(orgId);
 30	        result.processed += 1;
 31	
 32	        logger.debug("usage recomputed", {
 33	          orgId,
 34	          seats: usage.seatsUsed,
 35	          projects: usage.projectsUsed,
 36	          issues: usage.issuesUsed,
 37	          at: now.toISOString(),
 38	        });
 39	      } catch (error) {
 40	        result.failed += 1;
 41	        logger.error("usage rollup failed", {
 42	          orgId,
 43	          reason: error instanceof Error ? error.message : String(error),
 44	        });
 45	      }
 46	    }
 47	  });
 48	}

