 28	  onSubmit: (input: CreateProjectInput) => Promise<ActionResult<Project>>;
 29	};
 30	
 31	const VISIBILITY_OPTIONS: readonly SelectOption[] = [
 32	  { value: "private", label: "Private — invited project members only" },
 33	  { value: "org", label: "Organization — anyone in this org" },
 34	  { value: "public", label: "Public — anyone with the link" },
 35	];
 36	
 37	export function ProjectForm(props: ProjectFormProps): ReactElement | null {
 38	  const { orgId, members, defaultValues, onSubmit } = props;
 39	
 40	  const [name, setName] = useState(defaultValues?.name ?? "");
 41	  // An empty override means "follow the name"; typing in the field pins it.
 42	  const [slugOverride, setSlugOverride] = useState(defaultValues?.slug ?? "");
 43	  const [description, setDescription] = useState(
 44	    defaultValues?.description ?? "",
 45	  );
 46	  const [visibility, setVisibility] = useState<ProjectVisibility>(
 47	    defaultValues?.visibility ?? "org",
 48	  );
 49	  const [leadId, setLeadId] = useState<UserId | null>(
 50	    (defaultValues?.leadId as UserId | null | undefined) ?? null,
 51	  );
 52	  const [invalid, setInvalid] = useState<string | null>(null);
 53	
 54	  const { submit, pending, error } = useFormAction(onSubmit);
 55	
 56	  // Exactly the transformation the server applies, so the preview cannot lie.
 57	  const slug = slugOverride.length > 0 ? slugify(slugOverride) : slugify(name);
 58	  const reserved = slug.length > 0 && isReservedSlug(slug);
 59	
 60	  async function handleSubmit(): Promise<void> {
 61	    const parsed = createProjectSchema.safeParse({
 62	      orgId,
 63	      name,
 64	      slug,
 65	      key: defaultValues?.key ?? projectKeyFromName(name),
 66	      description: description.length === 0 ? null : description,
 67	      visibility,
 68	      leadId,
 69	      color: defaultValues?.color ?? "#6366f1",
 70	      targetDate: defaultValues?.targetDate ?? null,
 71	    });
 72	
 73	    if (!parsed.success) {
 74	      setInvalid(parsed.error.issues[0]?.message ?? "Check the form");
 75	      return;
 76	    }
 77	    setInvalid(null);
 78	    await submit(parsed.data);
 79	  }
 80	
 81	  const leadOptions: readonly SelectOption[] = [
 82	    { value: "", label: "No lead" },
 83	    ...members.map((member) => ({
 84	      value: member.userId,
 85	      label: member.user.name,
 86	    })),
 87	  ];
 88	
 89	  return (
 90	    <div className="project-form space-y-4">
 91	      <FormField name="name" label="Name" required>
 92	        <Input
 93	          name="name"
 94	          value={name}
 95	          placeholder="Payments platform"
 96	          onChange={setName}
 97	        />
 98	      </FormField>
 99	
100	      <FormField
101	        name="slug"
102	        label="URL slug"
103	        hint={slug.length > 0 ? `/projects/${slug}` : "Derived from the name"}
104	        error={reserved ? `"${slug}" is reserved` : null}
105	      >
106	        <Input
107	          name="slug"
108	          value={slugOverride}
109	          placeholder={slugify(name)}
110	          invalid={reserved}
111	          onChange={setSlugOverride}
112	        />
113	      </FormField>
114	
115	      <FormField name="description" label="Description">
116	        <Textarea
117	          name="description"
118	          rows={3}
119	          value={description}
120	          onChange={setDescription}
121	        />
122	      </FormField>
123	
124	      <FormField name="visibility" label="Visibility">
125	        <Select
126	          name="visibility"
127	          value={visibility}
128	          options={VISIBILITY_OPTIONS}
129	          onChange={(value) => setVisibility(value as ProjectVisibility)}
130	        />
131	      </FormField>
132	
133	      <FormField name="leadId" label="Project lead">
134	        <Select
135	          name="leadId"
136	          value={leadId ?? ""}
137	          options={leadOptions}
138	          onChange={(value) =>
139	            setLeadId(value.length === 0 ? null : (value as UserId))
140	          }
141	        />
142	      </FormField>
143	
144	      <ErrorMessage message={invalid ?? error?.message ?? null} />
145	
146	      <Button
147	        type="button"
148	        loading={pending}
149	        disabled={pending || reserved || name.length === 0}
150	        onClick={() => void handleSubmit()}
151	      >
152	        Save project
153	      </Button>
154	    </div>
155	  );
156	}

