  3	/**
  4	 * Editor for name, description, visibility, status, lead and colour.
  5	 *
  6	 * Owner D. Private to the project settings route. `updateProjectSchema` makes
  7	 * every field optional, so the form sends the whole set and lets the service
  8	 * diff them — which is also what produces `changedFields` on the event.
  9	 */
 10	
 11	import { useActionState } from "react";
 12	import { fieldErrorsFromZod } from "@/lib/errors";
 13	import { updateProjectSchema } from "@/schemas/project";
 14	import type { ActionResult } from "@/types/api";
 15	import type { OrgId, UserId } from "@/types/common";
 16	import type { MemberWithUser } from "@/types/member";
 17	import type { Project } from "@/types/project";
 18	
 19	export type ProjectSettingsFormProps = {
 20	  orgId: OrgId;
 21	  project: Project;
 22	  members: readonly MemberWithUser[];
 23	  onSubmit: (input: unknown) => Promise<ActionResult<Project>>;
 24	};
 25	
 26	type SettingsState = ActionResult<Project> | null;
 27	
 28	export function ProjectSettingsForm(props: ProjectSettingsFormProps) {
 29	  const { orgId, project, members, onSubmit } = props;
 30	
 31	  const [state, submit, pending] = useActionState<SettingsState, FormData>(
 32	    async (_previous, formData) => {
 33	      const leadId = String(formData.get("leadId") ?? "");
 34	      const description = String(formData.get("description") ?? "").trim();
 35	
 36	      const parsed = updateProjectSchema.safeParse({
 37	        orgId,
 38	        projectId: project.id,
 39	        name: String(formData.get("name") ?? ""),
 40	        description: description.length === 0 ? null : description,
 41	        visibility: String(formData.get("visibility") ?? project.visibility),
 42	        status: String(formData.get("status") ?? project.status),
 43	        color: String(formData.get("color") ?? project.color),
 44	        leadId: leadId.length === 0 ? null : (leadId as UserId),
 45	      });
 46	
 47	      if (!parsed.success) {
 48	        return {
 49	          ok: false,
 50	          error: {
 51	            code: "validation_failed",
 52	            message: "Check the fields below.",
 53	            fieldErrors: fieldErrorsFromZod(parsed.error),
 54	          },
 55	        };
 56	      }
 57	
 58	      return onSubmit(parsed.data);
 59	    },
 60	    null,
 61	  );
 62	
 63	  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};
 64	
 65	  return (
 66	    <form action={submit} className="space-y-5">
 67	      {state?.ok === true ? (
 68	        <p className="rounded bg-emerald-50 px-3 py-2 text-sm text-emerald-700">
 69	          Project updated.
 70	        </p>
 71	      ) : null}
 72	
 73	      <div className="space-y-1">
 74	        <label htmlFor="name" className="text-sm font-medium">
 75	          Name
 76	        </label>
 77	        <input
 78	          id="name"
 79	          name="name"
 80	          defaultValue={project.name}
 81	          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
 82	        />
 83	        {fieldErrors.name !== undefined ? (
 84	          <p className="text-xs text-rose-600">{fieldErrors.name[0]}</p>
 85	        ) : null}
 86	      </div>
 87	
 88	      <div className="space-y-1">
 89	        <label htmlFor="description" className="text-sm font-medium">
 90	          Description
 91	        </label>
 92	        <textarea
 93	          id="description"
 94	          name="description"
 95	          rows={4}
 96	          defaultValue={project.description ?? ""}
 97	          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
 98	        />
 99	      </div>
100	
101	      <div className="grid gap-4 sm:grid-cols-2">
102	        <div className="space-y-1">
103	          <label htmlFor="visibility" className="text-sm font-medium">
104	            Visibility
105	          </label>
106	          <select
107	            id="visibility"
108	            name="visibility"
109	            defaultValue={project.visibility}
110	            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
111	          >
112	            <option value="private">Private — people on the project</option>
113	            <option value="org">Organization — everybody here</option>
114	            <option value="public">Public — anybody with the link</option>
115	          </select>
116	        </div>
117	
118	        <div className="space-y-1">
119	          <label htmlFor="status" className="text-sm font-medium">
120	            Status
121	          </label>
122	          <select
123	            id="status"
124	            name="status"
125	            defaultValue={project.status}
126	            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
127	          >
128	            <option value="active">Active</option>
129	            <option value="paused">Paused</option>
130	            <option value="completed">Completed</option>
131	          </select>
132	        </div>
133	      </div>
134	
135	      <div className="grid gap-4 sm:grid-cols-2">
136	        <div className="space-y-1">
137	          <label htmlFor="leadId" className="text-sm font-medium">
138	            Lead
139	          </label>
140	          <select
141	            id="leadId"
142	            name="leadId"
143	            defaultValue={project.leadId ?? ""}
144	            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
145	          >
146	            <option value="">No lead</option>
147	            {members.map((member) => (
148	              <option key={member.id} value={member.userId}>
149	                {member.user.name}
150	              </option>
151	            ))}
152	          </select>
153	        </div>
154	
155	        <div className="space-y-1">
156	          <label htmlFor="color" className="text-sm font-medium">
157	            Colour
158	          </label>
159	          <input
160	            id="color"
161	            name="color"
162	            type="color"
163	            defaultValue={project.color}
164	            className="h-9 w-16 rounded border border-slate-300"
165	          />
166	        </div>
167	      </div>
168	
169	      <button
170	        type="submit"
171	        disabled={pending}
172	        className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
173	      >
174	        {pending ? "Saving…" : "Save project"}
175	      </button>
176	    </form>
177	  );
