  2	 * Project settings including archive.
  3	 *
  4	 * Owner D. Editing needs `project:update`; archiving needs `project:archive`,
  5	 * which sits higher in `ROLE_MATRIX` — so the archive block is gated
  6	 * separately rather than assumed from the first check.
  7	 *
  8	 * Must call (do not reimplement): can
  9	 */
 10	
 11	import { notFound } from "next/navigation";
 12	import type { Metadata } from "next";
 13	import { archiveProjectAction } from "@/actions/projects/archive-project";
 14	import { updateProjectAction } from "@/actions/projects/update-project";
 15	import { can } from "@/lib/permissions";
 16	import { listMembers } from "@/server/services/member-service";
 17	import { loadProjectContext } from "../../../_lib/project-context";
 18	import { ArchiveProjectPanel } from "./archive-project-panel";
 19	import { ProjectSettingsForm } from "./project-settings-form";
 20	
 21	type PageParams = { orgSlug: string; projectSlug: string };
 22	
 23	export const dynamic = "force-dynamic";
 24	
 25	export const metadata: Metadata = {
 26	  title: "Project settings",
 27	};
 28	
 29	const MEMBER_PICKER_LIMIT = 100;
 30	
 31	export default async function Page(props: {
 32	  params: Promise<PageParams>;
 33	  searchParams: Promise<Record<string, string | string[] | undefined>>;
 34	}) {
 35	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
 36	  const { orgSlug, projectSlug } = await props.params;
 37	  await props.searchParams;
 38	
 39	  const { org, actor, project } = await loadProjectContext(orgSlug, projectSlug);
 40	
 41	  const resource = {
 42	    kind: "project",
 43	    orgId: org.id,
 44	    projectId: project.id,
 45	    visibility: project.visibility,
 46	    leadId: project.leadId,
 47	  } as const;
 48	
 49	  if (!can(actor, "project:update", resource)) {
 50	    notFound();
 51	  }
 52	  const mayArchive = can(actor, "project:archive", resource);
 53	
 54	  const members = await listMembers(actor, {
 55	    orgId: org.id,
 56	    limit: MEMBER_PICKER_LIMIT,
 57	  });
 58	
 59	  return (
 60	    <div className="max-w-xl space-y-10">
 61	      <section className="space-y-6">
 62	        <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
 63	          Project details
 64	        </h2>
 65	        <ProjectSettingsForm
 66	          orgId={org.id}
 67	          project={project}
 68	          members={members.items}
 69	          onSubmit={updateProjectAction}
 70	        />
 71	      </section>
 72	
 73	      {mayArchive ? (
 74	        <section className="rounded-md border border-amber-200 bg-amber-50 p-6">
 75	          <h2 className="text-sm font-semibold text-amber-900">
 76	            Archive this project
 77	          </h2>
 78	          <p className="mt-2 text-sm text-amber-800">
 79	            Archiving hides the project and, by default, its issues. Nothing is
 80	            deleted — an owner can restore it from the project list.
 81	          </p>
 82	
 83	          <div className="mt-4">
 84	            <ArchiveProjectPanel
 85	              project={project}
 86	              actor={actor}
 87	              onConfirm={archiveProjectAction}
 88	            />
 89	          </div>
 90	        </section>
 91	      ) : null}
 92	    </div>
 93	  );
 94	}
