  3	/**
  4	 * Owns the open/closed state of the archive confirmation dialog.
  5	 *
  6	 * Owner D. A Server Component cannot hand `onClose` to a client dialog — event
  7	 * handlers are not serialisable — so the state lives here and the page passes
  8	 * only data and the Server Action.
  9	 */
 10	
 11	import { useState } from "react";
 12	import { ProjectArchiveDialog } from "@/components/domain/project/project-archive-dialog";
 13	import type { ActionResult } from "@/types/api";
 14	import type { Actor } from "@/types/member";
 15	import type { Project } from "@/types/project";
 16	
 17	export type ArchiveProjectPanelProps = {
 18	  project: Project;
 19	  actor: Actor;
 20	  onConfirm: (input: unknown) => Promise<ActionResult<Project>>;
 21	};
 22	
 23	export function ArchiveProjectPanel(props: ArchiveProjectPanelProps) {
 24	  const [open, setOpen] = useState(false);
 25	
 26	  return (
 27	    <>
 28	      <button
 29	        type="button"
 30	        onClick={() => setOpen(true)}
 31	        className="rounded-md border border-amber-400 bg-white px-4 py-2 text-sm font-medium text-amber-900"
 32	      >
 33	        Archive project…
 34	      </button>
 35	
 36	      <ProjectArchiveDialog
 37	        open={open}
 38	        project={props.project}
 39	        actor={props.actor}
 40	        onConfirm={props.onConfirm}
 41	        onClose={() => setOpen(false)}
 42	      />
 43	    </>
 44	  );
 45	}

