import type { OrgId } from "@/types/common";

const input = (orgId: OrgId, o: { name: string; slug?: string; key?: string }) => ({
  orgId, name: o.name, slug: o.slug ?? "x-slug", key: o.key ?? "",
  description: null, visibility: "org" as const, leadId: null, color: "#6366f1", targetDate: null,
});

let cleanup: () => void;
let off: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); off = registerUsageListeners(); });
afterAll(() => { off(); cleanup(); });

describe("scratch", () => {
  it("1+4: slots and meter", async () => {
    const t = await createTenant("s1", "free");
    await recomputeUsage(t.org.id);
    const p2 = await projectService.createProject(t.actors.admin, input(t.org.id, { name: "Second" }));
    expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(2);
    await expect(projectService.createProject(t.actors.admin, input(t.org.id, { name: "Third" }))).rejects.toThrow(/allows 2 projects/);
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: p2.id, archiveIssues: true });
    expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(1);
    const p3 = await projectService.createProject(t.actors.admin, input(t.org.id, { name: "Third" }));
    const events: unknown[] = [];
    const o = subscribe("project.restored", (p) => { events.push(p); });
    await expect(projectService.restoreProject(t.actors.admin, t.org.id, p2.id)).rejects.toThrow(/allows 2 projects/);
    expect(events).toHaveLength(0);
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: p3.id, archiveIssues: true });
    const r = await projectService.restoreProject(t.actors.admin, t.org.id, p2.id);
    expect(r.archivedAt).toBeNull();
    expect(events).toHaveLength(1);
    o();
    const meter = (await usageRepo.getUsage(t.org.id)).projectsUsed;
    expect(meter).toBe(2);
    expect((await recomputeUsage(t.org.id)).projectsUsed).toBe(meter);
  });

  it("2: keys", async () => {
    const t = await createTenant("s2", "growth");
    const a = await projectService.createProject(t.actors.admin, input(t.org.id, { name: "Web Vendors" }));
    expect(a.key).toBe("WV");
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: a.id, archiveIssues: true });
    const b = await projectService.createProject(t.actors.admin, input(t.org.id, { name: "Web Visitors" }));
    expect(b.key).toBe("WV2");
    const c = await projectService.createProject(t.actors.admin, input(t.org.id, { name: "Plat", key: "PLAT" }));
    expect(c.key).toBe("PLA2");
  });

  it("3+5: slugs and restore", async () => {
    const t = await createTenant("s3", "growth");
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, archiveIssues: true });
    const n = await projectService.createProject(t.actors.admin, input(t.org.id, { name: "Platform", slug: "platform" }));
    expect(n.slug).toBe("platform-2");
    const r = await projectService.restoreProject(t.actors.admin, t.org.id, t.project.id);
    expect(r.slug).toBe("platform");
    const events: unknown[] = [];
    const o = subscribe("project.restored", (p) => { events.push(p); });
    await expect(projectService.restoreProject(t.actors.admin, t.org.id, t.project.id)).rejects.toThrow();
    expect(events).toHaveLength(0);
    o();
  });

  it("6: status", async () => {
    const t = await createTenant("s6", "growth");
    const iss = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
    await expect(projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "completed" })).rejects.toThrow();
    const paused = await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "paused" });
    expect(paused.status).toBe("paused");
    const listed = await projectService.listProjects(t.actors.admin, { orgId: t.org.id, status: "paused", limit: 10, cursor: null });
    expect(listed.items.map((i) => i.project.id)).toContain(t.project.id);
    await expect(issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id))).rejects.toThrow();
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: iss.id, status: "done" });
    const done = await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "completed" });
    expect(done.status).toBe("completed");
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: iss.id, status: "todo" });
    const again = await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "completed" });
    expect(again.status).toBe("completed");
    expect(again.updatedAt).toBe(done.updatedAt);
    await expect(projectService.updateProject(t.actors.viewer, { orgId: t.org.id, projectId: t.project.id, status: "active" })).rejects.toThrow();
    const active = await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "active" });
    expect(active.status).toBe("active");
    // archive, restore keeps status
    await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "paused" });
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, archiveIssues: true });
    await expect(projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "active" })).rejects.toThrow();
    const back = await projectService.restoreProject(t.actors.admin, t.org.id, t.project.id);
    expect(back.status).toBe("paused");
  });
});
EOF
